package main

import (
	"errors"
	"regexp"
)

func RomanToInt(s string) (int, error) {
	if s == "" {
		return 0, errors.New("roman numeral string is empty")
	}
	valid := regexp.MustCompile("^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$")
	if !valid.MatchString(s) {
		return 0, errors.New("invalid roman numeral form")
	}
	vals := map[byte]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
	total := 0
	i := 0
	for i < len(s) {
		v := vals[s[i]]
		if i+1 < len(s) && v < vals[s[i+1]] {
			total += vals[s[i+1]] - v
			i += 2
		} else {
			total += v
			i++
		}
	}
	return total, nil
}
